begin;
create or replace function ikigai_n5_private.member_id() returns uuid language plpgsql set search_path='' as $$
declare uid uuid:=auth.uid();begin
 if uid is null or not exists(select 1 from auth.users u where u.id=uid and not coalesce(u.is_anonymous,false) and (u.banned_until is null or u.banned_until<=now())) then
  raise insufficient_privilege using message='Đăng nhập bằng tài khoản học viên để làm đề N5.';
 end if;
 return uid;
end$$;

create or replace function public.ikigai_n5_list() returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=ikigai_n5_private.member_id();is_teacher boolean;
begin
 select exists(select 1 from auth.users where id=uid and raw_app_meta_data->>'role'='teacher') into is_teacher;
 return coalesce((select jsonb_agg(jsonb_build_object(
  'id',e.id,'title',e.payload->>'title','audioSeconds',e.payload->'audioSeconds',
  'sectionCounts',(select jsonb_agg(jsonb_array_length(s.value->'questions') order by s.ordinality) from jsonb_array_elements(e.payload->'sections') with ordinality s),
  'totalQuestions',(select sum(jsonb_array_length(s.value->'questions')) from jsonb_array_elements(e.payload->'sections') s)
 ) order by e.id) from ikigai_n5_private.exams e where is_teacher or coalesce((e.payload->>'published')::boolean,false)),'[]');
end$$;

create or replace function public.ikigai_n5_start(p_exam text) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=ikigai_n5_private.member_id();a ikigai_n5_private.attempts;e jsonb;initial jsonb;is_teacher boolean;
begin
 perform pg_advisory_xact_lock(hashtextextended(uid::text||p_exam,0));
 select * into a from ikigai_n5_private.attempts where user_id=uid and exam_id=p_exam and result is null for update;
 if found then return ikigai_n5_private.state(a);end if;
 select payload into e from ikigai_n5_private.exams where id=p_exam;
 if e is null then raise exception 'Chưa có đề N5 này';end if;
 select exists(select 1 from auth.users where id=uid and raw_app_meta_data->>'role'='teacher') into is_teacher;
 if not is_teacher and not coalesce((e->>'published')::boolean,false) then raise insufficient_privilege using message='Đề N5 này chưa được phát hành.';end if;
 select jsonb_agg((select jsonb_agg(-1 order by q.ordinality) from jsonb_array_elements(s.value->'questions') with ordinality q) order by s.ordinality)
 into initial from jsonb_array_elements(e->'sections') with ordinality s;
 insert into ikigai_n5_private.attempts(user_id,exam_id,snapshot,answers,deadline)
 values(uid,p_exam,e,initial,now()+make_interval(secs=>(e->'sections'->0->>'seconds')::double precision)) returning * into a;
 return ikigai_n5_private.state(a);
end$$;

